def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0

    recent_len = 8 if n > 8 else n
    recent_start = n - recent_len
    recent_opp_c = 0
    recent_opp_d = 0
    recent_my_d = 0

    prevD = 0
    afterD_D = 0
    prevC = 0
    afterD_C = 0

    for i in range(n):
        a, b = history[i]

        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

        if a == 'C':
            my_c += 1
        else:
            my_d += 1

        if i >= recent_start:
            if b == 'C':
                recent_opp_c += 1
            else:
                recent_opp_d += 1
            if a == 'D':
                recent_my_d += 1

        if i > 0:
            pa = history[i - 1][0]
            if pa == 'D':
                prevD += 1
                if b == 'D':
                    afterD_D += 1
            else:
                prevC += 1
                if b == 'D':
                    afterD_C += 1

    opp_c_rate = opp_c / float(n)
    opp_d_rate = opp_d / float(n)

    pD_after_D = afterD_D / float(prevD) if prevD else 0.0
    pD_after_C = afterD_C / float(prevC) if prevC else 0.0

    # If the opponent has never defected and we have tested cooperation,
    # wait one round for a possible retaliatory defect, then exploit them.
    if opp_d == 0 and my_d > 0:
        if my_d == 1 and last_my == 'D':
            return 'C'
        return 'D'

    # No opponent defection at all: remain cooperative, but make a few
    # cautious tests to discover unconditional cooperators.
    if opp_d == 0:
        if 30 <= n <= 80:
            p = 0.004 + (n - 30) * 0.0005
            if rng.random() < p:
                return 'D'
        elif 80 < n <= 90:
            if rng.random() < 0.015:
                return 'D'
        return 'C'

    # If our latest move was a single exploratory D and the opponent just
    # cooperated despite still looking cooperative, wait one more round
    # before deciding whether they are exploitable.
    if (
        opp_c_rate >= 0.55
        and last_my == 'D'
        and last_opp == 'C'
        and pD_after_D <= 0.25
        and my_d <= 1
    ):
        return 'C'

    # Long recent punishment streaks usually mean unilateral cooperation is
    # not productive; defend rather than keep playing a sucker payoff.
    if last_opp == 'D' and recent_opp_d >= max(4, recent_len - 2):
        return 'D'

    # Recognize reactive but forgiving cooperators: they punish our D but do
    # not D after our C. Against them, keep mutual cooperation alive.
    reactive = (
        opp_c_rate >= 0.65
        and prevD >= 1
        and pD_after_D >= 0.60
        and pD_after_C <= 0.40
        and (pD_after_D - pD_after_C) >= 0.20
    )
    if reactive:
        if n == 98:
            return 'C'
        return 'C'

    # Enough evidence that they do not punish our D: exploit.
    exploitable = (
        opp_c_rate >= 0.55
        and prevD >= 1
        and pD_after_D <= 0.25
    )
    if exploitable:
        return 'D'

    # Strongly non-cooperative opponents: defect unless a recent cooperative
    # streak makes a brief conciliation worthwhile before the end.
    if opp_d_rate >= 0.70:
        if (
            last_opp == 'C'
            and recent_opp_c >= recent_len - 1
            and opp_c_rate >= 0.45
        ):
            return 'C'
        return 'D'

    # Opponent defected last round: choose between repair and punishment.
    if last_opp == 'D':
        # Isolated slip from an otherwise cooperative player.
        if opp_c_rate >= 0.80 and recent_opp_d <= 2:
            return 'C'

        # Try to break mutual-defection loops when the opponent is not too
        # aggressive and not too far into a long D streak.
        if (
            last_my == 'D'
            and opp_c_rate >= 0.45
            and recent_opp_d <= 4
            and n < 90
        ):
            if rng.random() < 0.35:
                return 'C'

        # If we had just been cooperating and they defected once, give a
        # forgiving signal when their overall behavior is still cooperative.
        if last_my == 'C' and opp_c_rate >= 0.60 and recent_opp_d <= 3:
            return 'C'

        return 'D'

    # Opponent cooperated last round.
    # Against very cooperative opponents, preserve CC; only defect if they
    # have shown that our recent D is tolerated.
    if opp_c_rate >= 0.75 and recent_opp_c >= recent_len - 1:
        if recent_my_d >= 3 and pD_after_D <= 0.45:
            return 'D'
        return 'C'

    # Moderate cooperative opponents: keep cooperating if recent behavior is
    # mostly mutual cooperation.
    if opp_c_rate >= 0.55 and recent_opp_c >= 6:
        return 'C'

    # Mixed or mostly defective opponents: defect unless a small repair seems
    # worthwhile in a recent mutual-cooperation context.
    if recent_opp_d >= 3 or opp_c_rate < 0.55:
        return 'D'

    if rng.random() < 0.30:
        return 'C'

    return 'D'
